CREATE OR REPLACE FUNCTION public.notify_pro_member_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pro uuid;
  v_pseudo text;
  v_group text;
begin
  if new.source <> 'member' then
    return new;
  end if;

  select id into v_pro from public.profiles where role = 'pro' order by created_at limit 1;

  if v_pro is null or v_pro = new.author_id then
    return new;
  end if;

  select pseudo into v_pseudo from public.community_profiles where user_id = new.author_id;

  if new.group_id is not null then
    select name into v_group from public.feed_groups where id = new.group_id;
  end if;

  insert into public.scheduled_notifications
    (user_id, channel, type, title, body, link, payload, scheduled_for, sent_at)
  values (
    v_pro, 'in_app', 'feed_post',
    case
      when new.group_id is null then 'Nouvelle publication sur le feed'
      else 'Nouvelle publication dans « ' || coalesce(v_group, 'un groupe') || ' »'
    end,
    coalesce(v_pseudo, 'Un membre') || ' : ' || left(coalesce(nullif(new.body, ''), new.title), 120),
    case
      when new.group_id is null then '/pro/feed'
      else '/groups/' || new.group_id::text
    end,
    jsonb_build_object('post_id', new.id, 'group_id', new.group_id),
    now(), now()
  );

  return new;
end;
$function$
